from pathlib import Path
import json,hashlib,numpy as np
p=Path(__file__).resolve().parent;base=p.parent;prior=json.loads((base/'graphite-width/SUMMARY.json').read_text());rows=[];data={};inputs={}
for item in prior['rows']:
 dr=base/item['folder'];fp=dr/'MATRICES.npz';a=np.load(fp);inputs[str(fp.relative_to(base))]=hashlib.sha256(fp.read_bytes()).hexdigest();K=a['K_fine'];g=a['g_fine'];d=len(K);n=d-1;Q=np.zeros((d,n))
